<?php
declare(strict_types=1);
require_once __DIR__ . '/../vendors/vendor_guard.php';
$vendorId=(int)$_SESSION['vendor_info']['id']; $clientId=(int)$_SESSION['user_info']['id'];
$_SESSION['current_dashboard']='messages_dashboard';
$stmt=$conn->prepare('SELECT DISTINCT mo.buyer_id AS client_id, COALESCE(NULLIF(mo.buyer_username,\'\'),c.username) AS client_name, c.email, c.phone FROM marketplace_orders mo INNER JOIN clients c ON c.id=mo.buyer_id WHERE mo.vendor_id=? ORDER BY client_name');
$stmt->bind_param('i',$vendorId);$stmt->execute();$customers=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$selectedClient=(int)($_GET['client_id']??0);$customer=null;foreach($customers as $c){if((int)$c['client_id']===$selectedClient){$customer=$c;break;}}
$thread=[];$key='';
if($customer){$key='direct:v'.$vendorId.':c'.$selectedClient;$stmt=$conn->prepare('SELECT sender_type,sender_id,recipient_type,recipient_id,subject,body,is_read,created_at FROM cnrbyte_messages WHERE conversation_key=? ORDER BY created_at ASC LIMIT 300');$stmt->bind_param('s',$key);$stmt->execute();$thread=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();$type='vendor';$stmt=$conn->prepare('UPDATE cnrbyte_messages SET is_read=1,read_at=NOW() WHERE conversation_key=? AND recipient_type=? AND recipient_id=?');$stmt->bind_param('ssi',$key,$type,$vendorId);$stmt->execute();$stmt->close();}
function vendor_chat_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CnrByte | Customer Chats</title><link rel="stylesheet" href="/cnrbyte/css/cnrbyte-modules.css"><link rel="stylesheet" href="/cnrbyte/css/header.css"></head><body>
<?php require __DIR__.'/../includes/header.php'; ?>
<main class="cnr-messages-layout"><section class="cnr-form-card"><h1>Customer chats</h1><p>Direct chats are available with customers who have placed an order with this business.</p><p><a class="cnr-header-link" href="/cnrbyte/messages/dashboard.pge.php">Order conversations & notifications</a></p>
<?php if(!$customers): ?><p class="cnr-empty-state">No customers are linked to this business yet. Customer chats become available after an order is placed.</p><?php else: ?><div class="cnr-order-list"><?php foreach($customers as $c): ?><a class="cnr-order-link <?=((int)$c['client_id']===$selectedClient?'is-active':'')?>" href="?client_id=<?=(int)$c['client_id']?>"><strong><?=vendor_chat_h($c['client_name'])?></strong><span><?=vendor_chat_h($c['email'])?></span><small>Client #<?=(int)$c['client_id']?></small></a><?php endforeach; ?></div><?php endif; ?></section>
<section class="cnr-form-card"><h2><?= $customer ? 'Chat with '.vendor_chat_h($customer['client_name']) : 'Choose a customer' ?></h2>
<?php if(!$customer): ?><p class="cnr-empty-state">Select a customer from the list to view and reply to direct messages.</p><?php else: ?><div class="cnr-message-thread"><?php if(!$thread): ?><p class="cnr-empty-state">No direct messages yet. Start the conversation below.</p><?php endif; ?><?php foreach($thread as $m): $mine=$m['sender_type']==='vendor'&&(int)$m['sender_id']===$vendorId; ?><article class="cnr-message <?=$mine?'is-mine':''?>"><div class="cnr-message-meta"><?=$mine?'You':'Customer'?> · <?=vendor_chat_h($m['created_at'])?></div><?php if(!empty($m['subject'])):?><strong><?=vendor_chat_h($m['subject'])?></strong><?php endif;?><p><?=nl2br(vendor_chat_h($m['body']))?></p></article><?php endforeach; ?></div>
<form method="post" action="/cnrbyte/messages/vendor_chat.run.php"><input type="hidden" name="csrf_token" value="<?=vendor_chat_h($_SESSION['csrf_token']??'')?>"><input type="hidden" name="client_id" value="<?=(int)$selectedClient?>"><label>Subject<input name="subject" maxlength="180" value="Business enquiry"></label><label>Message<textarea name="body" rows="4" maxlength="5000" required></textarea></label><button class="cnr-button" type="submit">Send message</button></form><?php endif; ?></section></main></body></html>
